import json
for name in ['baseline-packages.json', 'after-cpm-packages.json']:
    with open(name) as f:
        data = json.load(f)
    print(f'=== {name} ===')
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                print(f'  {pname} | {pkg[\"id\"]} | requested={pkg.get(\"requestedVersion\",\"?\")} resolved={pkg.get(\"resolvedVersion\",\"?\")}')
    print()
"

